/** Select popup presentation. A long list uses Sheet; no automatic option-count threshold. */
enum class SbSelectPresentation { Menu, Sheet }

/** Previous select JVM signature. */
@Deprecated("Binary bridge before presentation", level = DeprecationLevel.HIDDEN)
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun <T> SbSelectField(
    label: String,
    options: List<Pair<T, String>>,
    selected: T,
    onChange: (T) -> Unit,
    modifier: Modifier = Modifier,
    help: String? = null,
    error: String? = null,
    enabled: Boolean = true,
    disabledOptions: Set<T> = emptySet(),
    optional: Boolean = false,
    placeholder: String? = null,
    groups: Map<T, String> = emptyMap(),
) {
    SbSelectField(label, options, selected, onChange, modifier, help, error, enabled, disabledOptions, optional, placeholder, groups, SbSelectPresentation.Menu)
}

/**
 * Select (spec/02 §2.3): the field of SbTextField with the chosen word in body and chevron-down (24 dp, textMuted) at
 * the end; label, control and notes are one target with the role „Drop-down list“. A press opens SbMenu under the
 * control with one check row per option (the 16 dp accent check of spec/02 §4.18); a row closes the menu, then
 * [onChange] gets its value. [help] and [error] as SbTextField. For a long list pass presentation = SbSelectPresentation.Sheet; it opens fully expanded.
 * [disabledOptions] are rows that cannot be chosen (a native option's `disabled`; SbSegmented hands its own on when it
 * shows as this field, D99 (1)). A long chosen word wraps, the control grows. [optional] as SbTextField (D99 (3));
 * D100 (4): only for a select where „none“ is one of the [options]. [placeholder] (§14.12) = the word in textMuted
 * while no option is chosen (null = „Bitte wählen“ from the table). [groups] (§14.12) = the head over an option that
 * starts a group of the menu (the option's value to the head's word).
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun <T> SbSelectField(
    label: String,
    options: List<Pair<T, String>>,
    selected: T,
    onChange: (T) -> Unit,
    modifier: Modifier = Modifier,
    help: String? = null,
    error: String? = null,
    enabled: Boolean = true,
    disabledOptions: Set<T> = emptySet(),
    optional: Boolean = false,
    placeholder: String? = null,
    groups: Map<T, String> = emptyMap(),
    presentation: SbSelectPresentation = SbSelectPresentation.Menu,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    var expanded by remember { mutableStateOf(false) }
    val interaction = remember { MutableInteractionSource() }
    LaunchedEffect(enabled) { if (!enabled) expanded = false }
    val chosen = options.firstOrNull { it.first == selected }?.second
    val word = chosen ?: placeholder ?: sbMessages().selectPlaceholder
    Column(
        modifier
            .fillMaxWidth()
            .clickable(
                interactionSource = interaction,
                indication = null,
                enabled = enabled,
                role = Role.DropdownList,
                onClick = { expanded = true },
            )
            .semantics { if (error != null) error(error) },
        verticalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        SbFieldLabel(label, optional, enabled)
        Box {
            Row(
                Modifier
                    .sbFieldControl(interaction, error != null, enabled)
                    .padding(horizontal = t.space.s3),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(t.space.s2),
            ) {
                // D99 (1): a long choice wraps and the control grows; never cut with an ellipsis
                SbWrapText(word, ty.body, if (enabled && chosen != null) c.text else c.textMuted, Modifier.weight(1f))
                Icon(SebaroIcons.Outline.ChevronDown, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconLg))
            }
            if (presentation == SbSelectPresentation.Menu) SbMenu(
                expanded = expanded,
                onDismissRequest = { expanded = false },
                items = options.map { (value, text) ->
                    SbMenuItem(text, { onChange(value) }, enabled = value !in disabledOptions, checked = value == selected, group = groups[value])
                },
            )
        }
        if (expanded && enabled && presentation == SbSelectPresentation.Sheet) {
            SbBottomSheet(onDismissRequest = { expanded = false }, title = label,
                sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)) {
                val selectedIndex = options.indexOfFirst { it.first == selected && it.first !in disabledOptions }
                val first = if (selectedIndex >= 0) selectedIndex else options.indexOfFirst { it.first !in disabledOptions }
                val focus = remember { FocusRequester() }
                val scroll = rememberLazyListState(initialFirstVisibleItemIndex = first.coerceAtLeast(0))
                LazyColumn(Modifier.fillMaxWidth().selectableGroup(), state = scroll) {
                    items(options.size) { i ->
                        val (value, text) = options[i]
                        groups[value]?.let { SbWrapText(it, ty.label, c.text, Modifier.padding(t.spacing.gutter).semantics { heading() }) }
                        SbRadioRow(text, value == selected, onClick = { expanded = false; onChange(value) },
                            modifier = if (i == first) Modifier.focusRequester(focus) else Modifier,
                            enabled = value !in disabledOptions)
                        if (i == first) LaunchedEffect(first) { focus.requestFocus() }
                    }
                }
            }
        }
        SbFieldNotes(help, counter = null, error = error)
    }
}
